it.effect(
  "an owner's answer to an evaluator's question goes to the evaluator, not the worker",
  () =>
    Effect.gen(function* () {
      const fake = yield* makeFake;
      yield* Effect.gen(function* () {
        const { kanban, board } = yield* toyBoard;
        const evaluator: KanbanActor = { _tag: "evaluator", threadId: ThreadId.make("eval") };
        const card = yield* kanban.createCard(
          board.id,
          {
            prompt: "Fix the fee",
            title: "Fee",
            subtasks: [
              { text: "Write the PR", owner: "work" },
              { text: "Tell the reporter", owner: "evaluator" },
            ],
          },
          evaluator,
        );
        yield* kanban.dispatchNow;
        const workThread = (yield* kanban.card(card.id)).card.activeThreadId!;
        const worker: KanbanActor = { _tag: "thread", threadId: workThread };
        yield* kanban.markSubtask(card.id, "s1", "done", "PR #4", worker, "work");
        yield* kanban.moveCard(card.id, "completed", "owner", owner);
        yield* kanban.moveCard(card.id, "needs_owner", "evaluator", evaluator, {
          question: "Post this to the reporter?",
        });
        const discussion = yield* kanban.cardDiscussion(card.id);
        yield* kanban.post(discussion.id, owner, [{ _tag: "md", text: "Yes, post it" }]);
        const answered = (yield* kanban.card(card.id)).card;
        assert.strictEqual(answered.stage, "completed");
        assert.isNull(answered.question);
        assert.isNull(answered.wakeNote);
        const all = yield* Ref.get(fake.threads);
        assert.notInclude(all.get(workThread)!.messages.join("\n"), "Yes, post it");
        const evaluators = [...all.entries()].filter(([id]) => id !== workThread);
        assert.isTrue(
          evaluators.some(([, thread]) =>
            thread.messages.some((text) => text.includes("Yes, post it")),
          ),
        );
        yield* kanban.dispatchNow;
        assert.isNull((yield* kanban.card(card.id)).card.activeThreadId);
      }).pipe(Effect.provide(testLayer(fake.layer)));
    }),
);

it.effect.each([
  { previous: "evaluator", next: "work" },
  { previous: "evaluator", next: "review" },
  { previous: "script", next: "work" },
  { previous: "script", next: "review" },
] as const)("card_edit cannot remove a gate by changing $previous to $next", ({ previous, next }) =>
  Effect.gen(function* () {
    const fake = yield* makeFake;
    yield* Effect.gen(function* () {
      const { kanban, board } = yield* toyBoard;
      const evaluator: KanbanActor = { _tag: "evaluator", threadId: ThreadId.make("eval") };
      const card = yield* kanban.createCard(
        board.id,
        {
          title: "Gate owner",
          prompt: "Work",
          subtasks: [{ text: "Restart Robob", owner: previous }],
        },
        owner,
      );
      const patch = { subtasks: [{ id: "s1", text: "Restart Robob", owner: next }] };
      const denied = yield* kanban.editCard(card.id, patch, evaluator).pipe(Effect.flip);
      assert.include(denied.detail, "needs Abdullah's answer before it can be skipped");
      assert.strictEqual((yield* kanban.card(card.id)).card.subtasks[0]?.owner, previous);
      yield* kanban.askOwner(
        card.id,
        { question: "Approve s1?", blocking: false, action: { summary: "Approve s1" } },
        evaluator,
        "evaluator",
      );
      yield* kanban.answerAsk(card.id, "q1", { verdict: "approved", revision: 0 }, owner);
      const approved = yield* kanban.editCard(card.id, patch, evaluator);
      assert.strictEqual(approved.subtasks[0]?.owner, next);
      assert.isUndefined(approved.subtasks[0]?.gate);
    }).pipe(Effect.provide(testLayer(fake.layer)));
  }),
);

