const lastText = (messages: ReadonlyArray<{ readonly blocks: ReadonlyArray<unknown> }>) =>
  messages
    .at(-1)
    ?.blocks.map((b) => ("text" in (b as object) ? (b as { text: string }).text : ""))
    .join("") ?? "";

