      rekeyFailures.remaining = 1;
      const failed = yield* kanban
        .setPool(board.id, opusXhigh, undefined, { replaces: oldKey })
        .pipe(Effect.flip);
      assert.strictEqual(rekeyFailures.remaining, 0);
